pragma solidity ^0.4.19;

contract PRIVATE_ETH_CELL
{
mapping (address=>uint256) public balances;

uint public MinSum;

LogFile Log;

bool intitalized;

function SetMinSum(uint _val)
public
{
require(!intitalized);
MinSum = _val;
}

